use std::{ffi::OsString, path::PathBuf};

#[derive(clap::Args)]
pub(crate) struct CreateArgs {
    /// New archive file outside the native data directories.
    #[arg(long)]
    pub output: PathBuf,
    /// Existing creator secp256k1 private key; never generated by this command.
    #[arg(long)]
    pub signing_key: PathBuf,
    #[arg(long)]
    pub creator: Option<String>,
    #[arg(long)]
    pub source: Option<String>,
    /// Ordinary node options, after --. All native writers must remain stopped.
    #[arg(last = true)]
    pub node_args: Vec<OsString>,
}

fn run_create(args: &CreateArgs) -> eyre::Result<()> {
    let (manifest, public_key) = crate::snapshot::create::create(
        &args.output,
        &args.signing_key,
        args.creator.clone(),
        args.source.clone(),
        args.node_args.clone(),
    )?;
    println!("snapshot={} finalized_height={} finalized_hash={} files={} bytes={} creator_public_key={} signature=verified",
        args.output.display(), manifest.progress.finalized.number, manifest.progress.finalized.hash,
        manifest.file_count, manifest.total_bytes, hex::encode(public_key));
    Ok(())
}

pub(super) fn run(args: CreateArgs) -> eyre::Result<()> {
    run_create(&args)
}
